from django.payments import PaymentProcessor

def payment(request):
    processor = PaymentProcessor('stripe')
    if request.method == 'POST':
        payment_url = processor.create_session(
            amount=2000,
            currency='eur',
            product_name='Product',
            success_url='/success/',
            cancel_url='/cancel/'
        )
        return redirect(payment_url)
    return render(request, 'payment.html')
```

